#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_repeat;
uniform float amzp_progressa;
uniform float amzp_progress;
uniform float amzp_scale;
uniform float amzp_angle;
uniform float amzp_progressr;
uniform float amzp_progressg;
uniform float amzp_progressb;
    float4 newLayer( float4 a, float4 b) {
    return a * (1. - b.a) + b;
    }
    float2x2 rot2m(float a){
 float s = sin(a);
 float c = cos(a);
 return float2x2(c, -s, s, c);
    }
    float2 l2s( float2 v ) {
        return (float4(v,0.,1.)*amzLayerToScreen()).xy;
    }
   float hash(float2 p) {
     float h = dot(p,float2(127.1,311.7));
     return -1.0 + 2.0*fract(sin(h)*43758.5453123);
    }
    float noise(float2 p) {
     float2 i = floor(p);
     float2 f = fract(p);
     float2 u = f*f*(3.0-2.0*f);
     return mix(mix(hash( i + float2(0.0,0.0) ),
      hash( i + float2(1.0,0.0) ), u.x),
     mix( hash( i + float2(0.0,1.0) ),
      hash( i + float2(1.0,1.0) ), u.x), u.y);
    }
    float noise(float2 p, int oct) {
     float2x2 m = float2x2( 1.6, 1.2, -1.2, 1.6 );
     float f = 0.0;
     for(int i = 1; i < 3; i++){
      float mul = 1.0/pow(2.0, float(i));
      f += mul*noise(p);
      p = m*p;
     }
     return f;
    }
    void amzRender()
    {
        float4 texColor = amzTexture(0,amzScreenNorm().st);
     float4 result;
     float2 uvv = amzScreenNorm().st;
        float glitch = (amzp_repeat>0.5)? pow(cos((amzp_progressa+7.5)*0.5)*1.2+1.0, 1.2) : amzp_progressa;
        if(noise(0.5+float2(0, 0))*glitch > 0.62){
      uvv.y = mod(uvv.y+noise(float2(1.0*4.0, 0)), 1.2);
     }
        float2 satriyaid = ((float2(amzScreenNorm().x,1.0-amzScreenNorm().y)*screen.zw)-amzLayerCenter())/layer;
        satriyaid.y*=layer.y/layer.x;
     float2 hp = float2(amzp_progress, uvv.y);
        hp /= amzp_scale;
        hp *= rot2m((0.0+amzp_angle)*0.0174533);
     float nh = noise(hp*7.0+amzp_progress*10.0, 3) * (noise(hp+3.0*0.3)*0.8);
     nh += noise(hp*100.0+10.0*10.0, 3)*0.02;
     float rnd = 0.0;
     if(glitch > 0.0){
      rnd = hash(uvv);
      if(glitch < 1.0){
       rnd *= glitch;
      }
     }
     nh *= glitch + rnd;
     float r = amzTexture(0, uvv+float2(nh, amzp_progressr)*nh).r;
     float g = amzTexture(0, uvv+float2(nh-amzp_progressg, 0.0)*nh).g;
     float b = amzTexture(0, uvv+float2(nh, amzp_progressb)*nh).b;
     float3 col = float3(r, g, b);
     result = float4(col.rgb, 1.0);
            float4 targetLuma = result;
            const float3 luminanceWeighting = float3(0.2126, 0.7152, 0.0722);
            float luma = dot(targetLuma.rgb, luminanceWeighting);
            float lowThresholdB = (0.06*(1.0+0.05))-0.001;
            float lowThresholdA = lowThresholdB-max(0.05,0.00001);
            float highThresholdA = (1.0*(1.0+0.05)-0.05)+0.001;
            float highThresholdB = highThresholdA+max(0.05,0.00001);
            float lowBlend = smoothstep( lowThresholdA, lowThresholdB, luma );
            float highBlend = 1. - smoothstep( highThresholdA, highThresholdB, luma );
            float lumafx = min(lowBlend,highBlend);
            float4 fxLuma = targetLuma*lumafx;
     amzOutput = newLayer(texColor, fxLuma) * texColor.a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
